// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed parameter: an array of addresses; the key decision is whether it's empty or not
    function testFuzz_property(address[] memory tos) public {
        // Keep domain wide; no restrictive assumes. The deciding input is tos.length == 0.
        bool ok;
        // call transfer and observe whether it returns (ok=true) or reverts (ok=false)
        try c.transfer(msg.sender, address(0x1234), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the reference (correct) implementation requires _tos.length > 0 and thus
        // WILL revert when tos is empty; the mutant removed that require and therefore
        // WILL return true when tos is empty. Thus for ALL admissible inputs the reference
        // satisfies: if tos.length == 0 then the call does NOT succeed (ok == false).
        // The buggy mutant violates this for some input (specifically empty tos) where ok == true.
        if (tos.length == 0) {
            assertTrue(!ok);
        } else {
            // when tos non-empty both should succeed (the calls to the callee are to an EOA address here)
            assertTrue(ok);
        }
    }
}
